/**
 * One open project.
 */
public protocol EditorProtocol: AnyObject, Sendable {
    
    /**
     * Add a library item at the end of its lane. Returns the clip id.
     */
    func append(materialId: String) throws  -> String
    
    /**
     * The end of the last clip, in microseconds.
     */
    func durationUs() throws  -> Int64
    
    /**
     * The picture at `time_us`.
     */
    func frame(timeUs: Int64) throws  -> Frame
    
    /**
     * Copy a picked file into the project and add it to the library.
     * Returns the material id.
     */
    func `import`(path: String, media: Media) throws  -> String
    
    /**
     * The rows to draw, top first.
     */
    func lanes() throws  -> [Lane]
    
    func redo() throws 
    
    /**
     * Remove one clip.
     */
    func remove(clipId: String) throws 
    
    /**
     * Write the draft into the project folder.
     */
    func save() throws 
    
    /**
     * Cut a clip at `at_us`. Returns the right piece's id.
     */
    func split(clipId: String, atUs: Int64) throws  -> String
    
    func undo() throws 
    
}
